def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    # Step 1: Identify the most under-explored region
    objectives = [obj for _, obj in archive]
    obj1_vals = np.array([obj[0] for obj in objectives])
    obj2_vals = np.array([obj[1] for obj in objectives])

    if len(objectives) < 2:
        selected_idx = 0
    else:
        # Find the least crowded region in the Pareto front
        min_dist = np.inf
        selected_idx = 0
        for i in range(len(archive)):
            dist = np.inf
            for j in range(len(archive)):
                if i != j:
                    current_dist = np.sqrt((obj1_vals[i] - obj1_vals[j])**2 + (obj2_vals[i] - obj2_vals[j])**2)
                    if current_dist < dist:
                        dist = current_dist
            if dist < min_dist:
                min_dist = dist
                selected_idx = i

    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()

    # Step 2: Adaptive local search with temperature control
    temperature = 1.0 / (1.0 + np.exp(-len(archive)/10.0))  # Decreases as archive grows
    current_weight = np.sum(weight_lst[new_solution == 1])

    # Step 3: Value-balancing phase
    obj1_total = np.sum(value1_lst[new_solution == 1])
    obj2_total = np.sum(value2_lst[new_solution == 1])

    if obj1_total > obj2_total:
        # Improve obj2 by removing items with highest obj1/obj2 ratio
        in_items = np.where(new_solution == 1)[0]
        if len(in_items) > 0:
            ratios = value1_lst[in_items] / (value2_lst[in_items] + 1e-10)
            remove_candidates = in_items[np.argsort(-ratios)[:max(1, int(len(in_items)*0.2))]]
            for idx in remove_candidates:
                if current_weight - weight_lst[idx] >= 0 and np.random.rand() < temperature:
                    new_solution[idx] = 0
                    current_weight -= weight_lst[idx]
    else:
        # Improve obj1 by removing items with highest obj2/obj1 ratio
        in_items = np.where(new_solution == 1)[0]
        if len(in_items) > 0:
            ratios = value2_lst[in_items] / (value1_lst[in_items] + 1e-10)
            remove_candidates = in_items[np.argsort(-ratios)[:max(1, int(len(in_items)*0.2))]]
            for idx in remove_candidates:
                if current_weight - weight_lst[idx] >= 0 and np.random.rand() < temperature:
                    new_solution[idx] = 0
                    current_weight -= weight_lst[idx]

    # Step 4: Diversity-enhancing phase - add items from least represented solutions
    if len(archive) > 1:
        # Find items that are in the least represented solutions
        item_counts = np.zeros(len(weight_lst))
        for sol, _ in archive:
            item_counts += sol
        least_represented_items = np.argsort(item_counts)[:max(1, len(weight_lst)//10)]

        for idx in least_represented_items:
            if new_solution[idx] == 0 and current_weight + weight_lst[idx] <= capacity and np.random.rand() < temperature:
                new_solution[idx] = 1
                current_weight += weight_lst[idx]

    # Step 5: Random perturbation to escape local optima
    if np.random.rand() < 0.3 * temperature:
        k = min(3, len(weight_lst))
        flip_indices = np.random.choice(len(weight_lst), size=k, replace=False)
        for idx in flip_indices:
            if new_solution[idx] == 1:
                if current_weight - weight_lst[idx] >= 0:
                    new_solution[idx] = 0
                    current_weight -= weight_lst[idx]
            else:
                if current_weight + weight_lst[idx] <= capacity:
                    new_solution[idx] = 1
                    current_weight += weight_lst[idx]

    return new_solution
